use std::{collections::BTreeSet, fs, path::{Path, PathBuf}, process::Command, thread, time::{Duration, Instant}};
use std::os::unix::fs::PermissionsExt;
use zil_base::{Fingerprint, FingerprintBuilder, Limits, ModuleId, Phase, ResultCategory};
use zil_driver::{compile_path, CancellationToken, CodegenOptions, CompileOptions, CompileReport, NativeBackend, QueryDisposition, Stage};
use zil_ir::{wire, CandidatePlan, FunctionId, ScalarInterface, TypedProgram};

const ROOT: &str = "import left\nimport right\nfn value()->i64=>i64(#(left.make()))+i64(right.value())\n";
const LEFT: &str = "fn hidden()->i32=>40\npub fn make()->i32=>hidden()\nfn unused()->i32=>91\n";
const RIGHT: &str = "pub fn value()->i32=>2\n";
const CLANG: &str = "/workspace/scratch/ac5966c4c370/toolchains/llvm-23.1.4/bin/clang";

struct Case(PathBuf);
impl Case {
    fn new(root: &Path, name: &str) -> Self {
        let this = Self(root.join(name));
        fs::create_dir(&this.0).unwrap();
        this.put("main.zil", ROOT);
        this.put("left.zil", LEFT);
        this.put("right.zil", RIGHT);
        this
    }
    fn put(&self, path: &str, bytes: impl AsRef<[u8]>) {
        let path = self.0.join(path);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(path, bytes).unwrap();
    }
    fn options(&self) -> CompileOptions {
        CompileOptions {
            backend: NativeBackend::LlvmApi,
            stop_after: Stage::Build,
            entry: Some("value".into()),
            output: Some(self.0.join("program")),
            query_cache: Some(self.0.join("queries")),
            codegen: CodegenOptions { units: 1, jobs: 1 },
            ..CompileOptions::default()
        }
    }
    fn build(&self, label: &str, options: &CompileOptions) -> CompileReport {
        let report = compile_path(&self.0.join("main.zil"), options);
        self.put(&format!("{label}.json"), report.to_json());
        println!("{} {} {} {} Verify={}", self.0.file_name().unwrap().to_string_lossy(), label, report.status, report.query_cache.state, report.verification_runs);
        report
    }
    fn entry(&self, report: &CompileReport) -> PathBuf {
        self.0.join("queries/frontend-cp12-v1").join(format!("{}.qcp", report.query_cache.key.unwrap()))
    }
    fn executable(&self) -> Vec<u8> { fs::read(self.0.join("program")).unwrap() }
    fn wrapper(&self, body: &str) -> PathBuf {
        let path = self.0.join("clang-wrapper");
        fs::write(&path, body).unwrap();
        fs::set_permissions(&path, fs::Permissions::from_mode(0o700)).unwrap();
        path
    }
}
fn no_authority(interfaces: &[ScalarInterface]) {
    assert!(!interfaces.is_empty());
    for i in interfaces {
        assert!(i.result_origins.is_none());
        assert!(i.callable_returns.is_none());
        assert!(i.callable_contracts.is_none());
        assert!(i.contract_fingerprint.is_none());
    }
}
fn authority(interfaces: &[ScalarInterface]) {
    assert!(!interfaces.is_empty());
    for i in interfaces {
        assert!(i.result_origins.is_some());
        assert!(i.callable_returns.is_some());
        assert!(i.callable_contracts.is_some());
        assert!(i.contract_fingerprint.is_some());
    }
}
fn success(report: &CompileReport, state: &str, expected: &[u8]) {
    assert_eq!(report.status, ResultCategory::Success, "{}", report.to_json());
    assert_eq!(report.query_cache.state, state, "{}", report.to_json());
    assert_eq!(report.verification_runs, 1, "{}", report.to_json());
    assert_eq!(report.query_events.iter().filter(|e| e.phase == Phase::Verify).count(), 1);
    authority(&report.scalar_interfaces);
    let run = Command::new(&report.artifacts["executable"]).output().unwrap();
    assert!(run.status.success());
    assert_eq!(run.stdout, expected);
    assert!(run.stderr.is_empty());
}
fn size(bytes: &[u8], offset: usize) -> usize {
    usize::try_from(u64::from_le_bytes(bytes[offset..offset+8].try_into().unwrap())).unwrap()
}
fn wrap(pristine: &[u8], payload: &[u8]) -> Vec<u8> {
    let mut out = pristine[..80].to_vec();
    out[40..72].copy_from_slice(&Fingerprint::of(payload).0);
    out[72..80].copy_from_slice(&(payload.len() as u64).to_le_bytes());
    out.extend(payload);
    out
}
fn decode(pristine: &[u8]) -> (TypedProgram, CandidatePlan) {
    let payload = &pristine[80..];
    let start = 24 + 28 * size(payload, 16);
    let wire_end = start + size(payload, 0);
    let (module, candidate) = wire::decode_module_candidate(&payload[start..wire_end], &Limits::default()).unwrap();
    let program = wire::decode_query_cache_metadata(&payload[wire_end..], module, &Limits::default()).unwrap();
    (program, candidate)
}
fn encode(pristine: &[u8], program: &TypedProgram, candidate: &CandidatePlan) -> Vec<u8> {
    let old = &pristine[80..];
    let start = 24 + 28 * size(old, 16);
    let mut payload = old[..start].to_vec();
    let module = wire::encode_module_candidate(&program.module, candidate, &Limits::default()).unwrap();
    let metadata = wire::encode_query_cache_metadata(program, &Limits::default()).unwrap();
    payload[..8].copy_from_slice(&(module.len() as u64).to_le_bytes());
    payload[8..16].copy_from_slice(&(metadata.len() as u64).to_le_bytes());
    payload.extend(module);
    payload.extend(metadata);
    wrap(pristine, &payload)
}
fn hash_vectors(root: &Path) {
    let mut records = Vec::new();
    for n in [0usize, 1, 31, 55, 56, 63, 64, 65, 127, 128, 129, 4097] {
        let bytes = (0..n).map(|i| ((i * 73 + 19) % 256) as u8).collect::<Vec<_>>();
        let direct = Fingerprint::of(&bytes);
        for stride in [1, 3, 7, 64, 255] {
            let mut incremental = FingerprintBuilder::new();
            for chunk in bytes.chunks(stride) { incremental.update(chunk); }
            assert_eq!(incremental.digest(), direct);
        }
        records.push(format!("{{\"n\":{n},\"sha256\":\"{direct}\"}}"));
    }
    fs::write(root.join("sha256-vectors.json"), format!("[{}]", records.join(","))).unwrap();
}
fn source_and_limits(root: &Path) {
    let case = Case::new(root, "source-limits");
    let options = case.options();
    let first = case.build("cold", &options);
    success(&first, "miss", b"42\n");
    assert!(first.query_cache.stored);
    let warm = case.build("warm", &options);
    success(&warm, "hit", b"42\n");
    assert_eq!(first.scalar_interfaces, warm.scalar_interfaces);
    for phase in [Phase::Expand, Phase::Ct, Phase::Types, Phase::Analyze] {
        assert!(warm.query_events.iter().any(|e| e.phase == phase && e.disposition == QueryDisposition::Reused));
    }
    let mut keys = BTreeSet::from([first.query_cache.key.unwrap()]);
    let variants: [(&str, &str, String, &[u8]); 5] = [
        ("equal-size-private", "left.zil", LEFT.replace("40", "41"), b"43\n"),
        ("equal-size-unused", "left.zil", LEFT.replace("91", "92"), b"42\n"),
        ("trivia", "left.zil", format!("{LEFT}// review-only trivia\n"), b"42\n"),
        ("import-order", "main.zil", ROOT.replace("import left\nimport right", "import right\nimport left"), b"42\n"),
        ("import-alias", "main.zil", ROOT.replace("import left", "import left as lhs").replace("left.make", "lhs.make"), b"42\n"),
    ];
    for (name, file, content, expected) in variants {
        case.put("main.zil", ROOT); case.put("left.zil", LEFT);
        case.put(file, &content);
        let report = case.build(name, &options);
        success(&report, "miss", expected);
        assert!(keys.insert(report.query_cache.key.unwrap()));
    }
    case.put("main.zil", ROOT); case.put("left.zil", LEFT);
    fs::create_dir(case.0.join("left")).unwrap();
    fs::rename(case.0.join("left.zil"), case.0.join("left/mod.zil")).unwrap();
    let moved = case.build("same-bytes-new-path", &options);
    success(&moved, "miss", b"42\n");
    assert!(keys.insert(moved.query_cache.key.unwrap()));
    fs::rename(case.0.join("left/mod.zil"), case.0.join("left.zil")).unwrap();
    for index in 0..11 {
        let mut changed = options.clone();
        match index {
            0 => changed.limits.max_source_bytes -= 1,
            1 => changed.limits.max_tokens -= 1,
            2 => changed.limits.max_nodes -= 1,
            3 => changed.limits.max_functions -= 1,
            4 => changed.limits.max_blocks -= 1,
            5 => changed.limits.max_instructions -= 1,
            6 => changed.limits.max_locals -= 1,
            7 => changed.limits.max_values -= 1,
            8 => changed.limits.max_analysis_steps -= 1,
            9 => changed.limits.max_ct_steps -= 1,
            10 => changed.limits.max_call_depth -= 1,
            _ => unreachable!(),
        }
        let report = case.build(&format!("limit-{index}"), &changed);
        success(&report, "miss", b"42\n");
        assert!(keys.insert(report.query_cache.key.unwrap()));
    }
    let mut explicit = options.clone();
    explicit.build_inputs = Fingerprint::of(b"independent-explicit-input");
    let changed = case.build("explicit-build-input", &explicit);
    success(&changed, "miss", b"42\n");
    assert!(keys.insert(changed.query_cache.key.unwrap()));
    success(&case.build("restore-all-inputs", &options), "hit", b"42\n");
    let old_entry = fs::read(case.entry(&first)).unwrap();
    let old_exe = case.executable();
    case.put("right/mod.zil", RIGHT);
    let ambiguity = case.build("new-ambiguity", &options);
    assert!(ambiguity.diagnostics.iter().any(|d| d.code == "E-MODULE-AMBIGUOUS"));
    assert_eq!(ambiguity.verification_runs, 0);
    assert_eq!(ambiguity.query_cache.state, "bypass");
    assert_eq!(case.executable(), old_exe);
    fs::remove_file(case.0.join("right/mod.zil")).unwrap();
    fs::remove_file(case.0.join("program")).unwrap();
    fs::hard_link(case.0.join("left.zil"), case.0.join("program")).unwrap();
    let overlap = case.build("output-hardlinks-source", &options);
    assert!(overlap.diagnostics.iter().any(|d| d.code == "E-OUTPUT-SOURCE"));
    assert_eq!(overlap.verification_runs, 0);
    assert_eq!(overlap.query_cache.state, "bypass");
    assert_eq!(fs::read(case.0.join("left.zil")).unwrap(), LEFT.as_bytes());
    assert_eq!(fs::read(case.entry(&first)).unwrap(), old_entry);
    fs::remove_file(case.0.join("program")).unwrap();
    success(&case.build("after-current-input-rejections", &options), "hit", b"42\n");
}
fn codec_and_verify(root: &Path) {
    let case = Case::new(root, "codec-verify");
    let options = case.options();
    let first = case.build("cold", &options);
    success(&first, "miss", b"42\n");
    let entry = case.entry(&first);
    let pristine = fs::read(&entry).unwrap();
    case.put("pristine.qcp", &pristine);
    let (program, candidate) = decode(&pristine);
    no_authority(&program.interfaces);
    for index in 0..4 {
        let mut elevated = program.clone();
        match index {
            0 => elevated.interfaces[0].result_origins = Some(vec![]),
            1 => elevated.interfaces[0].callable_returns = Some(vec![]),
            2 => elevated.interfaces[0].callable_contracts = Some(vec![]),
            3 => elevated.interfaces[0].contract_fingerprint = Some(Fingerprint::ZERO),
            _ => unreachable!(),
        }
        assert!(wire::encode_query_cache_metadata(&elevated, &Limits::default()).is_err());
    }
    for index in 0..8 {
        let bad = if index < 4 {
            let mut payload = pristine[80..].to_vec();
            match index {
                0 => { let a=payload[24..52].to_vec(); let b=payload[52..80].to_vec(); payload[24..52].copy_from_slice(&b); payload[52..80].copy_from_slice(&a); }
                1 => payload[36..44].copy_from_slice(&u64::MAX.to_le_bytes()),
                2 => payload[44..52].copy_from_slice(&u64::MAX.to_le_bytes()),
                3 => payload[..8].copy_from_slice(&u64::MAX.to_le_bytes()),
                _ => unreachable!(),
            }
            wrap(&pristine, &payload)
        } else {
            let mut changed = program.clone();
            match index {
                4 => changed.interfaces.reverse(),
                5 => changed.module.module_id = ModuleId(u32::MAX),
                6 => changed.module.source_fingerprint = Fingerprint::ZERO,
                7 => changed.module.target.id.push_str("-foreign"),
                _ => unreachable!(),
            }
            encode(&pristine, &changed, &candidate)
        };
        case.put(&format!("mutation-{index}.qcp"), &bad);
        fs::write(&entry, &bad).unwrap();
        let report = case.build(&format!("corrupt-{index}"), &options);
        success(&report, "corrupt", b"42\n");
        assert!(report.query_cache.stored);
        assert_eq!(fs::read(&entry).unwrap(), pristine);
    }
    let old_exe = case.executable();
    let mut invalid = candidate.clone();
    invalid.functions[0].function = FunctionId(u32::MAX);
    let bad = encode(&pristine, &program, &invalid);
    fs::write(&entry, &bad).unwrap();
    case.put("invalid-function-id.qcp", &bad);
    let rejected = case.build("valid-codec-invalid-candidate", &options);
    assert_ne!(rejected.status, ResultCategory::Success, "{}", rejected.to_json());
    assert_eq!(rejected.phase, Phase::Verify);
    assert_eq!(rejected.query_cache.state, "hit");
    assert_eq!(rejected.verification_runs, 1);
    assert_eq!(rejected.query_events.iter().filter(|e| e.phase == Phase::Verify).count(), 1);
    assert!(!rejected.query_cache.stored);
    no_authority(&rejected.scalar_interfaces);
    assert_eq!(fs::read(&entry).unwrap(), bad);
    assert_eq!(case.executable(), old_exe);
    fs::write(&entry, &pristine).unwrap();
    success(&case.build("restore-candidate", &options), "hit", b"42\n");
}
fn linking_and_cancellation(root: &Path) {
    let case = Case::new(root, "link-failure");
    let mut options = case.options();
    options.clang = Some(case.wrapper(&format!("#!/bin/sh\nexec {CLANG} \"$@\"\n")));
    let first = case.build("cold", &options);
    success(&first, "miss", b"42\n");
    let pristine = fs::read(case.entry(&first)).unwrap();
    let old_exe = case.executable();
    case.wrapper("#!/bin/sh\nexit 23\n");
    let failure = case.build("warm-same-linker-path-now-fails", &options);
    assert_eq!(failure.query_cache.state, "hit");
    assert_ne!(failure.status, ResultCategory::Success);
    assert_eq!(failure.verification_runs, 1);
    assert!(!failure.query_cache.stored);
    assert_eq!(case.executable(), old_exe);
    assert_eq!(fs::read(case.entry(&first)).unwrap(), pristine);
    case.wrapper(&format!("#!/bin/sh\nexec {CLANG} \"$@\"\n"));
    success(&case.build("restored-linker", &options), "hit", b"42\n");

    let case = Case::new(root, "late-cancel");
    let mut options = case.options();
    let signal = case.0.join("link-entered");
    let release = case.0.join("link-release");
    let script = format!("#!/bin/sh\n: > '{}'\nwhile [ ! -f '{}' ]; do sleep 0.01; done\nexec {CLANG} \"$@\"\n", signal.display(), release.display());
    options.clang = Some(case.wrapper(&script));
    case.put("program", b"old-executable-sentinel");
    case.put("program.ll", b"old-ir-sentinel");
    let token = options.cancellation.clone();
    let waiter = thread::spawn(move || {
        let deadline = Instant::now() + Duration::from_secs(25);
        while !signal.exists() && Instant::now() < deadline { thread::sleep(Duration::from_millis(2)); }
        assert!(signal.exists(), "linker barrier was not reached");
        token.cancel();
        fs::write(release, b"cancelled").unwrap();
    });
    let cancelled = case.build("cancel-while-linking", &options);
    waiter.join().unwrap();
    assert_eq!(cancelled.status, ResultCategory::Cancelled, "{}", cancelled.to_json());
    assert_eq!(cancelled.query_cache.state, "miss");
    assert_eq!(cancelled.verification_runs, 1);
    assert!(!cancelled.query_cache.stored);
    assert_eq!(case.executable(), b"old-executable-sentinel");
    assert_eq!(fs::read(case.0.join("program.ll")).unwrap(), b"old-ir-sentinel");
    assert_eq!(fs::read_dir(case.0.join("queries/frontend-cp12-v1")).unwrap().count(), 0);
    options.cancellation = CancellationToken::new();
    case.wrapper(&format!("#!/bin/sh\nexec {CLANG} \"$@\"\n"));
    let recovered = case.build("fresh-after-late-cancel", &options);
    success(&recovered, "miss", b"42\n");
    assert!(recovered.query_cache.stored);
}
fn main() {
    let root = PathBuf::from(std::env::args().nth(1).expect("output directory"));
    fs::create_dir(&root).unwrap();
    hash_vectors(&root);
    source_and_limits(&root);
    codec_and_verify(&root);
    linking_and_cancellation(&root);
    fs::write(root.join("PASS"), "independent CP12 controls passed\n").unwrap();
}

